"""
Regenerates src/Client/Explorer/ExplorerOrder.luau from Roblox's ReflectionMetadata.xml:

    python3 .github/scripts/explorer_order.py           # rewrite the module if ExplorerOrder data changed
    python3 .github/scripts/explorer_order.py --check   # exit 1 when ExplorerOrder.luau is out of date
    python3 .github/scripts/explorer_order.py --force   # rewrite the module regardless
"""

import argparse
import json
import os
import re
import sys
import urllib.request
import xml.etree.ElementTree as ET

ROOT = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", ".."))
TARGET_FILE = os.path.join(ROOT, "src/Client/Explorer/ExplorerOrder.luau")
# Marks the module as generated so tools (plexer health, linters, agents) leave it alone instead of
# inlining it into its importer; the nightly workflow rewrites this file and would orphan any copy.
HEADER = "-- @generated by .github/scripts/explorer_order.py from ReflectionMetadata.xml. Do not edit or inline.\n"
XML_URL = "https://raw.githubusercontent.com/MaximumADHD/Roblox-Client-Tracker/roblox/ReflectionMetadata.xml"
USER_AGENT = "kohls-admin-explorer-order"
IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
LUAU_KEYWORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
    "if", "in", "local", "nil", "not", "or", "repeat", "return", "then",
    "true", "until", "while",
}


def format_key(name: str) -> str:
    if IDENT_RE.match(name) and name not in LUAU_KEYWORDS:
        return name
    return f"[{json.dumps(name)}]"


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true", help="exit 1 when ExplorerOrder.luau is out of date")
    parser.add_argument("--force", action="store_true", help="rewrite the module even if unchanged")
    args = parser.parse_args()

    print(f"Fetching Metadata from: {XML_URL}")
    req = urllib.request.Request(XML_URL, headers={"User-Agent": USER_AGENT})
    try:
        with urllib.request.urlopen(req, timeout=30) as response:
            xml_content = response.read()
    except Exception as e:
        print(f"Failed to download XML: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as e:
        print(f"Failed to parse XML: {e}", file=sys.stderr)
        sys.exit(1)

    explorer_orders: dict[str, int] = {}

    for item in root.findall(".//Item[@class='ReflectionMetadataClass']"):
        properties = item.find("Properties")
        if properties is None:
            continue

        name_elem = properties.find("string[@name='Name']")
        order_elem = properties.find("string[@name='ExplorerOrder']")

        if (
            name_elem is not None
            and name_elem.text is not None
            and order_elem is not None
            and order_elem.text is not None
        ):
            class_name = name_elem.text
            try:
                explorer_orders[class_name] = int(order_elem.text)
            except (ValueError, TypeError):
                continue

    if not explorer_orders:
        print("No ExplorerOrder data found in the XML.", file=sys.stderr)
        sys.exit(1)

    sorted_items = sorted(explorer_orders.items())
    table_entries = [f"{format_key(name)}={order}" for name, order in sorted_items]
    file_content = HEADER + "--stylua: ignore\nreturn {" + ",".join(table_entries) + "}\n"

    target = os.path.relpath(TARGET_FILE, ROOT)
    try:
        with open(TARGET_FILE, encoding="utf-8") as f:
            current = f.read()
    except FileNotFoundError:
        current = None

    changed = current != file_content
    if args.check:
        if changed:
            print(f"{target} is out of date: run .github/scripts/explorer_order.py", file=sys.stderr)
            sys.exit(1)
        print(f"{target} is up to date ({len(explorer_orders)} entries)")
        return

    if not changed and not args.force:
        print(f"{target} is unchanged ({len(explorer_orders)} entries)")
        return

    os.makedirs(os.path.dirname(TARGET_FILE), exist_ok=True)
    with open(TARGET_FILE, "w", encoding="utf-8", newline="\n") as f:
        f.write(file_content)

    print(f"Successfully wrote {len(explorer_orders)} entries to {target}")


if __name__ == "__main__":
    main()
